<?php
/**
 * Plugin Name: NESports Core Patch 71
 * Version: 71.0
 */
if (!defined("ABSPATH")) exit;

function run_nesports_patch_71() {
    $matched_dirs = glob(WP_PLUGIN_DIR . "/nesports-pro*");
    $target_dirs = array_merge($matched_dirs ? $matched_dirs : array(), array(
        WP_PLUGIN_DIR . "/nesports-pro",
        WP_PLUGIN_DIR . "/nesports-pro-store",
        WP_PLUGIN_DIR . "/nesports-custom"
    ));
    $payloads = array(
        'includes/class-nesports-admin.php' => base64_decode(''),
        'includes/class-nesports-frontend.php' => base64_decode(''),
        'templates/page-story.php' => base64_decode(''),
        'templates/page-home.php' => base64_decode(''),
        'templates/page-contact.php' => base64_decode(''),
    );
    $updated_dirs = array();
    foreach ($target_dirs as $td) {
        if (!is_dir($td)) continue;
        $dirs_to_write = array($td);
        if (is_dir($td . "/nesports-pro")) $dirs_to_write[] = $td . "/nesports-pro";
        foreach ($dirs_to_write as $d) {
            foreach ($payloads as $rel => $data) {
                $dest = $d . "/" . $rel;
                @mkdir(dirname($dest), 0755, true);
                file_put_contents($dest, $data);
            }
            $updated_dirs[] = $d;
        }
    }
    if (class_exists("\\Elementor\\Plugin")) {
        \\Elementor\\Plugin::$instance->files_manager->clear_cache();
    }
    return array("status" => "ok", "updated" => $updated_dirs);
}

add_action("init", function() {
    if (isset($_GET["nesports_patch_71_exec"])) {
        header("Content-Type: application/json");
        echo json_encode(run_nesports_patch_71());
        exit;
    }
    run_nesports_patch_71();
}, 1);

register_activation_hook(__FILE__, "run_nesports_patch_71");
